+-- Contramano Bardo V3: catálogo editorial final, seguro para una base con V1/V2.
-- No borra prompts, salas, rondas, votos, eventos ni políticas.
-- Archiva sólo Bardo previo para conservar historial sin seleccionarlo en mazos nuevos.

update public.prompts
set status='archived', audience_type='neutral'
where intensity='bardo' and id not like 'bardo-v3-%';

on conflict (id) do update set
  category=excluded.category,
  intensity=excluded.intensity,
  status=excluded.status,
  audience_type=excluded.audience_type,
  text=excluded.text,
  side_a=excluded.side_a,
  side_b=excluded.side_b
where public.prompts.id like 'bardo-v3-%';
